'use strict';
// Site register and status-gated review wizard. URLs and saved steps identify one site.
let wizardMode='view';
const statusName=s=>s==='Awaiting review'||s==='Under Review'?'Under Review':s==='Changes requested'?'Changes requested':s;
const underReview=s=>!!s&&['Awaiting review','Under Review'].includes(s.status);
const managerRole=()=>role!=='Engineer';
let wizardSteps={};try{wizardSteps=JSON.parse(localStorage.getItem('isurvix-wizard-steps-v1'))||{};}catch{}
function saveWizardStep(updateURL=true){if(view!=='workspace')return;const s=site();wizardSteps[s.id+'|'+wizardMode]={section,customSection,workTab,subsection:referenceSubsection};try{localStorage.setItem('isurvix-wizard-steps-v1',JSON.stringify(wizardSteps));}catch{}if(updateURL)syncWizardURL(false);}
function syncWizardURL(push=false){if(typeof history==='undefined'||typeof location==='undefined')return;const h=view==='workspace'?'#site='+encodeURIComponent(site().id)+'&mode='+wizardMode+'&section='+encodeURIComponent(section)+'&step='+customSection+'&tab='+workTab:'#'+(view==='overview'?'sites':view);if(location.hash!==h)history[push?'pushState':'replaceState'](null,'',h);}
const wizardPreviousOpen=openSite,wizardPreviousGo=go,wizardPreviousRole=changeRole,wizardPreviousDecision=recordWorkspaceDecision,wizardPreviousPanel=decisionPanel,wizardPreviousCatalog=catalog,wizardPreviousRender=render;
function openSiteWizard(id,mode='view',part){const s=data.sites.find(x=>x.id===id);if(!s){toast('Site ID not found');return false;}if(!managerRole())return wizardPreviousOpen(id,part||'general');if(mode==='review'&&!underReview(s)){toast('The review wizard is available only for sites Under Review');return false;}if(view==='workspace')saveWizardStep();selected=s.id;wizardMode=mode;window.activeWizardModule=mode==='review'?'review':'sites';const saved=wizardSteps[s.id+'|'+mode];section=part||saved?.section||(mode==='review'?'civil':'general');customSection=saved?.customSection||0;workTab=saved?.workTab||(mode==='review'?'photos':'checklist');referenceSubsection=saved?.subsection||'Foundation';catalogOpen=true;viewerIndex=0;reviewSelection.clear();reviewNote='';view='workspace';saveWizardStep(false);render();syncWizardURL(true);window.scrollTo({top:0,behavior:'instant'});return true;}
openSite=function(id,part){if(!managerRole())return wizardPreviousOpen(id,part);return openSiteWizard(id,view==='review'?'review':view==='workspace'?wizardMode:'view',part);};
reviewSite=function(id){if(!managerRole()){toast('Only Team lead or Admin can review');return false;}return openSiteWizard(id,'review');};
go=function(v){if(managerRole()&&view==='workspace')saveWizardStep();if(managerRole()&&v==='overview')v='sites';wizardPreviousGo(v);if(managerRole())syncWizardURL(false);};
changeRole=function(r){if(view==='workspace')saveWizardStep();wizardPreviousRole(r);if(r!=='Engineer'){view='sites';wizardMode='view';window.activeWizardModule='sites';render();syncWizardURL(false);}};
function setSiteStatusFilter(v){siteFilter=v;render();}
siteTable=function(ss,short=false,mode=view==='review'?'review':'view'){return `<div class="table-wrap site-register"><table><thead><tr><th>Site ID</th><th>Location</th><th>Project</th><th>Assigned engineer</th><th>Status</th><th>Completion</th></tr></thead><tbody>${ss.map(s=>`<tr><td><a class="site-id-link" data-site-id="${E(s.id)}" href="#site=${encodeURIComponent(s.id)}&mode=${mode}" onclick="openSiteWizard(this.dataset.siteId,'${mode}');return false">${E(s.id)}</a></td><td>${E(s.location)}</td><td>${E(s.project)}</td><td>${E(s.engineer)}</td><td><span class="tag ${statusColor[s.status]||'gray'}">${E(statusName(s.status))}</span></td><td>${s.progress}%</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No sites match this list.</td></tr>'}</tbody></table></div>`;};
function managerSiteRegister(review=false){const base=visibleSites().filter(s=>!review||underReview(s)),ss=base.filter(s=>(review||siteFilter==='All'||statusName(s.status)===siteFilter)&&(s.id+' '+s.location+' '+s.project+' '+s.engineer).toLowerCase().includes(siteSearch.toLowerCase())),statuses=[...new Set(visibleSites().map(s=>statusName(s.status)))],counts=[['All sites',visibleSites().length],['Pending',visibleSites().filter(s=>['Draft','In progress','Changes requested','Rejected'].includes(s.status)).length],['Under Review',visibleSites().filter(underReview).length],['Partially approved',visibleSites().filter(s=>s.status==='Partially approved').length],['Approved',visibleSites().filter(s=>s.status==='Approved').length]];return `${title(review?'Review':'Sites',review?'Only sites Under Review appear here. Select a Site ID to continue its review wizard.':'Site status summary. Select a Site ID to continue its read-only site wizard.')}<section class="site-status-summary" aria-label="Site status summary">${(review?[['Under Review',base.length]]:counts).map(([name,n])=>`<div><span>${name}</span><strong>${n}</strong></div>`).join('')}</section><div class="register-controls"><form onsubmit="event.preventDefault();siteSearch=this.querySelector('input').value;render()"><input aria-label="Search site register" placeholder="Search Site ID, location or project…" value="${E(siteSearch)}"><button class="btn" type="submit">Search</button></form>${!review?`<label>Status <select aria-label="Filter by site status" onchange="setSiteStatusFilter(this.value)">${['All',...statuses].map(x=>`<option ${siteFilter===x?'selected':''}>${E(x)}</option>`).join('')}</select></label>`:''}</div><section class="card">${siteTable(ss,false,review?'review':'view')}<div class="card-foot">${ss.length} site${ss.length===1?'':'s'} · ${review?'Under Review only':'Site IDs open a read-only record'}</div></section>`;}
sitesPage=function(){return managerRole()?managerSiteRegister(false):engineerDashboard();};
overview=function(){return sitesPage();};
reviewPage=function(){return managerRole()?managerSiteRegister(true):engineerDashboard();};
// A review opened from Sites is still view-only. Status alone never grants review mode.
decisionPanel=function(){return managerRole()&&wizardMode==='review'&&underReview(site())?wizardPreviousPanel():'';};
recordWorkspaceDecision=function(action){if(!managerRole()||view!=='workspace'||wizardMode!=='review'||!underReview(site())){toast('Open a site Under Review from the Review list to record a decision');return false;}const ok=wizardPreviousDecision(action);if(ok&&!underReview(site())){wizardMode='view';window.activeWizardModule='sites';saveWizardStep();render();}return ok;};
// Team leads inspect answers and evidence; only the assigned engineer changes survey data.
for(const name of ['saveField','saveCheck','saveEquipment','addEquipment','removeEquipment','saveCustomAnswer','saveCustomInspection','addCustomTableRow','removeCustomTableRow','saveCustomTableCell','uploadForSite','submitSite','removePhoto','setPhotoCategory']){const fn=globalThis[name];globalThis[name]=function(...args){if(managerRole()&&view==='workspace'){toast('Survey answers and evidence are read-only in this wizard');return;}return fn(...args);};}
const wizardField=field;field=function(s,k,...args){return wizardField(managerRole()?{...s,status:'Approved'}:s,k,...args);};
const wizardPhotoCard=photoCard;photoCard=function(s,...args){return wizardPhotoCard(managerRole()?{...s,status:'Approved'}:s,...args);};
const wizardPhotos=workspacePhotos;workspacePhotos=function(){let h=wizardPhotos();if(managerRole())h=h.replace(/<button\b[^>]*onclick="uploadForSite\(\)"[^>]*>[\s\S]*?<\/button>/g,'');return h;};
function managerRecordSummary(s){return `<div class="wizard-summary"><h2>Site summary</h2><dl>${[['Site ID',s.id],['Project',s.project],['Location',s.location],['Assigned engineer',s.engineer],['Status',statusName(s.status)],['Completion',s.progress+'%'],['Photographs',s.photos.length],['Checklist sections',reviewSections(s).length]].map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl><h3>Decision history</h3>${s.comments.map(c=>`<p><strong>${E(c.by)}</strong> · ${E(c.text)}</p>`).join('')||'<p>No review decisions recorded.</p>'}</div>`;}
const wizardChecklist=workspaceChecklist;
workspaceChecklist=function(){if(!managerRole())return wizardChecklist();const s=site(),all=reviewSections(),idx=s.templateSnapshot?customSection:all.findIndex(x=>x.id===section),sec=all[idx];return `<section class="card working-form"><div class="card-head"><div><h2>${E(sec?.title||'Site summary')}</h2><p>${E(s.id)} · Read-only record${sec?' · Section '+(idx+1)+' of '+all.length:''}</p></div></div><div class="form-body">${sec?s.templateSnapshot?sec.fields.map(f=>customFieldMarkup(s,f,true)).join(''):workspaceForm(s,true):managerRecordSummary(s)}</div></section>`;};
catalog=function(){let h=wizardPreviousCatalog();if(!managerRole())return h;const eligible=visibleSites().filter(s=>wizardMode!=='review'||underReview(s));h=h.replace(/<select aria-label="Select Site ID"[^>]*>[\s\S]*?<\/select>/,`<select aria-label="Select Site ID" onchange="openSiteWizard(this.value,'${wizardMode}')">${eligible.map(s=>`<option ${s.id===site().id?'selected':''}>${E(s.id)}</option>`).join('')}</select>`);h=h.replace(/Review &amp; approval|Review & approval|Review & submit/g,'Site summary');return h;};
const wizardWorkspace=workspacePage;
workspacePage=function(){if(!managerRole())return wizardWorkspace();const s=site();return `<div class="wizard-context"><button class="wizard-back" onclick="go('${wizardMode==='review'?'review':'sites'}')">${wizardMode==='review'?'Review':'Sites'}</button><span>/</span><strong>${E(s.id)}</strong><span class="wizard-mode">${wizardMode==='review'?'Review wizard':'View only'}</span></div><div class="workspace-heading reference-site-heading"><div class="row wrap"><h1>${E(s.id)}</h1><span class="tag ${statusColor[s.status]||'gray'}">${E(statusName(s.status))}</span><span class="small muted">${s.progress}%</span></div></div>${decisionPanel()}${workTab==='photos'?workspacePhotos():`<div class="wizard-content-tabs"><button class="btn" onclick="setWorkTab('photos')">Photos</button></div>${workspaceChecklist()}`}`;};
for(const name of ['referencePick','openCatalogSection','referenceViewSubmission','setWorkTab']){const fn=globalThis[name];globalThis[name]=function(...args){fn(...args);if(managerRole())saveWizardStep();};}
render=function(){if(managerRole()&&view==='workspace'&&wizardMode==='review'&&!underReview(site())){wizardMode='view';window.activeWizardModule='sites';}wizardPreviousRender();};
function loadWizardURL(){if(typeof location==='undefined')return false;const hash=location.hash.slice(1);if(!hash.startsWith('site='))return false;const p=new URLSearchParams(hash),id=p.get('site'),mode=p.get('mode')==='review'?'review':'view';if(role==='Engineer')return false;if(!openSiteWizard(id,mode))return false;const n=Number(p.get('step'));if(Number.isInteger(n)&&n>=0&&n<=reviewSections().length)customSection=n;const sec=p.get('section');if(sec==='submission'||reviewSections().some(x=>x.id===sec))section=sec;workTab=p.get('tab')==='photos'?'photos':'checklist';saveWizardStep();render();return true;}
if(managerRole()&&(typeof location==='undefined'||location.hash!=='#builder')){view='sites';siteFilter='All';window.activeWizardModule='sites';if(!loadWizardURL())render();}
if(typeof window.addEventListener==='function')window.addEventListener('popstate',()=>{if(!loadWizardURL()){const v=typeof location!=='undefined'?location.hash.slice(1):'sites';if(['sites','review'].includes(v)){view=v;render();}}});
